-- Satya Incense — Пахощі, свічки та ритуальні товари
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'satyaincense.com' OR LOWER(`name`) = 'satya incense')), 1, 0);
