-- Інтенти запасного пошуку Елі для «Езотерики» (php tools/eli-intents.php sql | grep esoterics)
INSERT INTO search_intents (term_stem, category_id, subcategory_id, weight) SELECT 'езотерик', (SELECT id FROM categories WHERE slug = 'esoterics' LIMIT 1), NULL, 1 FROM DUAL WHERE (SELECT id FROM categories WHERE slug = 'esoterics' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM search_intents si WHERE si.term_stem = 'езотерик' AND si.category_id <=> (SELECT id FROM categories WHERE slug = 'esoterics' LIMIT 1) AND si.subcategory_id <=> NULL);
INSERT INTO search_intents (term_stem, category_id, subcategory_id, weight) SELECT 'езотеричн', (SELECT id FROM categories WHERE slug = 'esoterics' LIMIT 1), NULL, 1 FROM DUAL WHERE (SELECT id FROM categories WHERE slug = 'esoterics' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM search_intents si WHERE si.term_stem = 'езотеричн' AND si.category_id <=> (SELECT id FROM categories WHERE slug = 'esoterics' LIMIT 1) AND si.subcategory_id <=> NULL);
INSERT INTO search_intents (term_stem, category_id, subcategory_id, weight) SELECT 'окультизм', (SELECT id FROM categories WHERE slug = 'esoterics' LIMIT 1), NULL, 1 FROM DUAL WHERE (SELECT id FROM categories WHERE slug = 'esoterics' LIMIT 1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM search_intents si WHERE si.term_stem = 'окультизм' AND si.category_id <=> (SELECT id FROM categories WHERE slug = 'esoterics' LIMIT 1) AND si.subcategory_id <=> NULL);
